def transform(grid):
    out=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    blocks=[]
    for r in range(R-2):
        for c in range(C-2):
            color=grid[r][c]
            if color and all(grid[i][j]==color for i in range(r,r+3) for j in range(c,c+3)):
                blocks.append((r,c,color))
    # Cast row and column rays across the canvas. Original marks are preserved,
    # except the ray's color overwrites them. At a crossing, the pixel stays empty.
    for r,c,color in blocks:
        for j in range(C):
            if not c<=j<c+3: out[r+1][j]=color
        for i in range(R):
            if not r<=i<r+3: out[i][c+1]=color
    # Determine crossing points between each pair of block centerlines.
    for r,c,_ in blocks:
        for rr,cc,_ in blocks:
            if r!=rr and c!=cc:
                out[r+1][cc+1]=0
                out[rr+1][c+1]=0
    return out
