def transform(grid):
    out=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    blocks=[]
    for r in range(R-2):
        for c in range(C-2):
            color=grid[r][c]
            if color and all(grid[i][j]==color for i in range(r,r+3) for j in range(c,c+3)):
                blocks.append((r+1,c+1,color))
    horizontal={r:color for r,c,color in blocks}
    vertical={c:color for r,c,color in blocks}
    for r,color in horizontal.items():
        out[r]=[color]*C
    for c,color in vertical.items():
        for r in range(R): out[r][c]=color
    # Crossings of perpendicular beams are left as background.
    for r in horizontal:
        for c in vertical:
            out[r][c]=0
    return out
